import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    results = []

    index = 1
    for _ in range(t):
        x = int(data[index])
        index += 1

        if x == 0:
            results.append("1 1")
        elif x == 1:
            results.append("-1")
        else:
            # Calculate n and m
            m = 2
            n = (x + m * m - 1) // (m * m)
            if n < m:
                results.append("-1")
            else:
                results.append(f"{n} {m}")

    print("\n".join(results))

if __name__ == "__main__":
    main()
